def longestPalindrome(s: str, t: str) -> int:
    n, m = len(s), len(t)

    # Palindromic-substring tables for s and t.
    palS = [[False] * n for _ in range(n)]
    for i in range(n - 1, -1, -1):
        palS[i][i] = True
        for j in range(i + 1, n):
            if s[i] == s[j] and (j == i + 1 or palS[i + 1][j - 1]):
                palS[i][j] = True
    palT = [[False] * m for _ in range(m)]
    for i in range(m - 1, -1, -1):
        palT[i][i] = True
        for j in range(i + 1, m):
            if t[i] == t[j] and (j == i + 1 or palT[i + 1][j - 1]):
                palT[i][j] = True

    # Longest palindrome starting at each index of s / ending at each index of t.
    best_start_s = [0] * (n + 1)
    for i in range(n):
        for j in range(i, n):
            if palS[i][j]:
                best_start_s[i] = max(best_start_s[i], j - i + 1)
    best_end_t = [0] * m
    for j in range(m):
        for i in range(j + 1):
            if palT[i][j]:
                best_end_t[j] = max(best_end_t[j], j - i + 1)

    ans = 0
    # Palindrome taken entirely from one string (the other substring is empty).
    for i in range(n):
        ans = max(ans, best_start_s[i])
    for j in range(m):
        ans = max(ans, best_end_t[j])

    # match[i][j] = longest L with s[i+p] == t[j-p] for p in [0, L).
    # This pairs a prefix of A (from s) with a reversed suffix of B (from t).
    match = [[0] * m for _ in range(n)]
    for i in range(n - 1, -1, -1):
        for j in range(m):
            if s[i] == t[j]:
                inner = match[i + 1][j - 1] if (i + 1 < n and j - 1 >= 0) else 0
                match[i][j] = 1 + inner

    for i in range(n):
        for j in range(m):
            L = match[i][j]
            if L == 0:
                continue
            ans = max(ans, 2 * L)                       # symmetric arms, empty middle
            if i + L < n:                               # extend middle inside s
                ans = max(ans, 2 * L + best_start_s[i + L])
            if j - L >= 0:                              # extend middle inside t
                ans = max(ans, 2 * L + best_end_t[j - L])
    return ans
